// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    address deployer;

    function setUp() public {
        address __invmut_eoa = address(uint160(0xE0A));
        vm.deal(__invmut_eoa, 100 ether);
        vm.startPrank(__invmut_eoa, __invmut_eoa);
        c = new PoCGame(address(this), 0);
        vm.stopPrank();
        deployer = __invmut_eoa;
    }

    function testFuzz_property(uint256 jump, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(jump > 0);

        // owner opens the contract to the public
        vm.startPrank(deployer, deployer);
        c.OpenToThePublic();
        vm.stopPrank();

        // time advances past the wager block so play() is reachable and wager is valid
        vm.roll(block.number + bound(jump, 1, 1000));

        // a real person tries to wager once the contract is public
        vm.deal(actor, 1 ether);
        vm.prank(actor, actor);
        bool wagerOk;
        try c.wager{value: 0}() {
            wagerOk = true;
        } catch {
            wagerOk = false;
        }

        // general rule: once the owner has opened the contract, any real person can wager
        assertTrue(wagerOk);
    }
}
